('08965abb-2655-4f21-903d-05a55c461d75', 'masala-tea', 'Masala Tea', 'A fragrant blend of traditional spices that creates a rich, comforting cup of authentic masala tea.', 40, 'https://yjdqepjcvfygkmvrsyoi.supabase.co/storage/v1/object/public/product-images/a4c3ccdd-ce4e-4252-b096-12ecd73b4660.jpg', 0, 1, '2026-06-22 11:50:35'),
('9720c36a-73ab-4718-9843-62cc392c1bb7', 'turmeric-powder', 'Turmeric Powder', 'Naturally processed turmeric powder rich in color and flavor, perfect for everyday cooking.', 40, 'https://yjdqepjcvfygkmvrsyoi.supabase.co/storage/v1/object/public/product-images/1b78017b-cae1-42f0-ba4e-fa3f43cd8804.jpg', 0, 1, '2026-06-22 11:49:10'),
('11f33fd4-fd89-4892-be78-8be27571f0a3', 'ginger-powder', 'Ginger Powder', 'Pure dried ginger powder with a warm, aromatic taste, suitable for cooking and beverages.', 40, 'https://yjdqepjcvfygkmvrsyoi.supabase.co/storage/v1/object/public/product-images/007641a3-a8f9-4818-8356-d5941fa80487.jpg', 0, 1, '2026-06-22 11:47:35'),
('e0fe0e14-2b72-4c6c-bc77-27cb4f92d154', 'dalle-powder', 'Dalle Powder', 'Finely ground dalle chilli powder that adds authentic Bhutanese heat and flavor to any dish.', 200, 'https://yjdqepjcvfygkmvrsyoi.supabase.co/storage/v1/object/public/product-images/261e52de-90b5-4ac4-a598-b99131c07c1e.jpg', 0, 1, '2026-06-22 11:46:39'),
('0b047168-a105-432d-baad-eb9749aeede8', 'dalle-paste', 'Dalle Paste', 'A ready-to-use spicy paste made from fresh dalle chillies, ideal for cooking and seasoning.', 50, 'https://yjdqepjcvfygkmvrsyoi.supabase.co/storage/v1/object/public/product-images/a31a45e1-c49f-49eb-a242-c716f122defe.jpg', 0, 1, '2026-06-22 11:45:10'),
('7df2411c-d442-4934-8cb0-de6ef15bcbea', 'dalle-chutney', 'Dalle Chutney', 'A flavorful Indian style chutney made from dalle chillies, perfect as a dip or condiment.', 100, 'https://yjdqepjcvfygkmvrsyoi.supabase.co/storage/v1/object/public/product-images/f915b06b-adaa-4958-bdda-ecc02a96b27a.jpg', 0, 1, '2026-06-22 11:43:03'),
('b40b3646-545c-460a-8513-99727d03f5ad', 'green-chilli-pickle', 'Chilli Pickle', 'A classic spicy pickle crafted from fresh chillies and natural ingredients for everyday enjoyment.', 50, 'https://yjdqepjcvfygkmvrsyoi.supabase.co/storage/v1/object/public/product-images/10b9fd2d-1163-496a-90bf-e10d03d922a6.jpg', 0, 1, '2026-06-22 11:40:49'),
('3daea090-78df-417d-9295-aeaddd2a26dd', 'dalle-pickle', 'Dalle Pickle', 'Authentic Bhutanese dalle chillies pickled using traditional methods for an intense spicy kick.', 100, 'https://yjdqepjcvfygkmvrsyoi.supabase.co/storage/v1/object/public/product-images/b841ad9e-1d51-40bb-925e-45db3fb1ba27.jpg', 0, 1, '2026-06-22 11:38:53'),
('ff7e5e43-9b46-481f-b54b-709864670039', 'red-dalle-pickle', 'Red Dalle Pickle', 'Made from premium red dalle chillies, delivering a bold, fiery flavor loved by spice enthusiasts.', 100, 'https://yjdqepjcvfygkmvrsyoi.supabase.co/storage/v1/object/public/product-images/322de175-39ca-41b6-9264-fa49a2a6f8fb.jpg', 0, 1, '2026-06-22 11:35:31'),
('59479b60-be80-465f-8b8a-1d876e681dfd', 'garlic-with-chilli-pickle', 'Garlic with Chilli Pickle', 'A bold, home-style pickle made with whole garlic cloves and green chillies, slow-pickled in oil with mustard seed, fenugreek and turmeric. Naturally preserved and completely chemical-free.', 150, 'https://yjdqepjcvfygkmvrsyoi.supabase.co/storage/v1/object/public/product-images/cc99ea33-478f-4357-b4b3-a0e5c5a39513.jpg', 0, 1, '2026-06-22 10:53:32'),
('5c8188b6-958f-4939-9d78-d0ab56af31d2', 'pumpkin-soup', 'Pumpkin Soup', 'A naturally sweet and savory dried soup mix made from sun-ripened Bhutanese pumpkin. Blended with coriander, onion leaves, garlic and a hint of Sichuan pepper for a warming, no-fuss bowl of soup.', 30, 'https://yjdqepjcvfygkmvrsyoi.supabase.co/storage/v1/object/public/product-images/31b682cf-05ed-4262-a987-ab81daaff60d.jpg', 0, 1, '2026-06-22 10:53:28'),
('066d5c17-def4-4bec-8531-7ac3c66f6481', 'oyster-mushroom-soup', 'Oyster Mushroom Soup', 'A wholesome dried soup mix made with farm-grown oyster mushrooms from Sarpang, Bhutan. Just add hot water for a comforting, earthy bowl of soup — naturally flavorful with no preservatives or added sugar.', 30, 'https://yjdqepjcvfygkmvrsyoi.supabase.co/storage/v1/object/public/product-images/66a58ea6-fc32-4b4f-acc5-fdc82f7d90f0.jpg', 0, 1, '2026-06-22 10:53:25'),
('85c918d1-9aff-49de-80b0-895827b8a338', 'mixed-vegetable-pickle', 'Mixed Vegetable Pickle', 'A flavorful blend of fresh vegetables pickled with aromatic spices for a crunchy, delicious taste.', 150, 'https://yjdqepjcvfygkmvrsyoi.supabase.co/storage/v1/object/public/product-images/daf9abd2-5a2c-43a0-a272-414e8c763edb.jpg', 0, 1, '2026-06-22 07:48:10'),
('bc197782-220f-4056-9719-60e1e785c503', 'mango-pickle', 'Mango Pickle', 'A tangy and spicy homemade mango pickle made with fresh mangoes and traditional Bhutanese spices.', 150, 'https://yjdqepjcvfygkmvrsyoi.supabase.co/storage/v1/object/public/product-images/50ac9204-67f1-48c1-966c-5c195202ef9a.jpg', 0, 1, '2026-06-22 07:46:08');
